#!/bin/sh
# ck.sh <step-name> <Creation Kit args...>: one Creation Kit phase in the game copy.
# Answers the "Script Source Extraction" prompt with No from inside the container, keeps
# ckpe.log and any crash report per attempt, and records exit code and duration.
# Do not edit this file while it runs: sh reads it as it goes.
D=$(cd "$(dirname "$0")" && pwd); . "$D/env.sh"
N=$1-$(date +%H%M); shift; mkdir -p "$BUILD/backup"
CR="$GAMECOPY/CreationKitPlatformExtendedCrashReport.log"
rm -f "$GAMECOPY/ckpe.log"; [ -e "$CR" ] && mv "$CR" "$BUILD/backup/crash-before-$N.log"
cd "$GAMECOPY" && start=$(date +%s)
"$D/run.sh" ./CreationKit.exe "$@" > "$BUILD/ck-$N.out" 2>&1 &
RUN=$!
for i in $(seq 1 120); do
  P=$(pgrep -f "^\./CreationKit\.exe -" | head -1); [ -n "$P" ] && break; sleep 2
done
[ -n "$P" ] && (timeout 400 "$D/inject.sh" "$P" "$(printf '%s' "$XEDIT/clickok.exe" | sed 's|/|\\|g; s|^|Z:|')" \
  "Script Source Extraction" "&No" 300 >/dev/null 2>&1 &)
wait $RUN; rc=$?
cp "$GAMECOPY/ckpe.log" "$BUILD/ck-$N.log" 2>/dev/null; [ -e "$CR" ] && cp "$CR" "$BUILD/backup/crash-$N.log"
echo "rc=$rc seconds=$(( $(date +%s) - start ))" >> "$BUILD/ck-$N.out"
grep -c "OUT OF HANDLE ARRAY ENTRIES" "$BUILD/ck-$N.log" 2>/dev/null | sed 's/^/handle-errors=/' >> "$BUILD/ck-$N.out"
grep -c "visibility task did not complete" "$BUILD/ck-$N.log" 2>/dev/null | sed 's/^/vis-incomplete=/' >> "$BUILD/ck-$N.out"
